package com.aoo.bcg.common.cache;import com.aoo.bcg.gamespi.time.AuthoritativeTimeSource;import java.time.Duration;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class ClubMemberCacheScaleTest{@Test void millionKeysSpreadAndHotMissIsSingleFlight()throws Exception{var router=new CacheShardRouter(64);int[]counts=new int[64];for(int i=1;i<=1_000_000;i++)counts[router.shard("1-"+i)]++;int min=Arrays.stream(counts).min().orElseThrow(),max=Arrays.stream(counts).max().orElseThrow();assertTrue((double)max/min<1.08);var cache=new ProtectedLookupCache<String,String>(AuthoritativeTimeSource.systemUtc(),Duration.ofMinutes(1),Duration.ofSeconds(3),1000);var loads=new AtomicInteger();try(var pool=Executors.newFixedThreadPool(64)){var start=new CountDownLatch(1);List<Future<Optional<String>>>futures=new ArrayList<>();for(int i=0;i<64;i++)futures.add(pool.submit(()->{start.await();return cache.get("hot",key->{loads.incrementAndGet();try{Thread.sleep(20);}catch(InterruptedException e){Thread.currentThread().interrupt();}return Optional.of("value");});}));start.countDown();for(var f:futures)assertEquals("value",f.get().orElseThrow());}assertEquals(1,loads.get());cache.invalidate("hot");assertEquals(0,cache.size());}}
